static std::string BuildAmdgpuMfmaSignatureList() {
    std::string list;
    for (const auto &cfg : amdgpu_mfma::MFMAConfig::GetConfigs()) {
        if (!list.empty()) {
            list += ", ";
        }
        list += cfg.name.str();
    }
